  '</td></tr>' + (o.footer ? '<tr><td style="padding:18px 30px 0;font:12px/1.6 Arial;color:#6B6862;text-align:center">' + o.footer + '</td></tr>' : '') + '</table></div>';
const n = JSON.parse($json.candidates[0].content.parts[0].text), f = $('Cohort Facts').first().json, l = a => '<ul>' + (a || []).map(x => '<li>' + x + '</li>').join('') + '</ul>';
return [{ json: { html: brand({ owner: cfg.ownerName, label: 'Workflow 19', title: 'Course Post-Mortem', paras: ['Cohort of ' + f.cohort + ', ' + f.finished + ' finished or exited.'], html: '<h3>What Worked</h3>' + l(n.worked) + '<h3>What Underperformed</h3>' + l(n.underperformed) + '<h3>What To Change Next Time</h3>' + l(n.change_next) }) } }];
